import * as React from "react";

import { cn } from "../lib/utils";

import styles from "./text.module.css";

let ruler: CanvasRenderingContext2D | null | undefined;

const transforms: Record<string, (text: string) => string> = {
  uppercase: (text) => text.toUpperCase(),
  lowercase: (text) => text.toLowerCase(),
  capitalize: (text) =>
    text.replace(
      /(^|\s)(\S)/g,
      (_, space: string, letter: string) => space + letter.toUpperCase(),
    ),
};

function measurerFor(node: HTMLElement) {
  if (ruler === undefined)
    ruler = document.createElement("canvas").getContext("2d");
  const context = ruler;
  if (!context) return null;
  const style = getComputedStyle(node);
  context.font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
  context.letterSpacing =
    style.letterSpacing === "normal" ? "0px" : style.letterSpacing;
  context.wordSpacing =
    style.wordSpacing === "normal" ? "0px" : style.wordSpacing;
  context.fontKerning = style.fontKerning === "none" ? "none" : "normal";
  const transform = transforms[style.textTransform];
  return (text: string) => {
    const collapsed = text.replace(/[ \t\n\r\f]+/g, " ");
    return context.measureText(transform ? transform(collapsed) : collapsed)
      .width;
  };
}

export function MiddleTruncate({
  children,
  text,
  keepEnd = 8,
  mono = false,
  title,
  className,
  onCopy,
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<"span">, "children" | "title"> & {
  children?: string;
  text?: string;
  keepEnd?: number;
  mono?: boolean;
  title?: string | false;
} & { ref?: React.Ref<HTMLSpanElement> }) {
  const value = text ?? children ?? "";
  const host = React.useRef<HTMLSpanElement>(null);
  const [visible, setVisible] = React.useState(value);
  React.useImperativeHandle(ref, () => host.current!, []);
  React.useLayoutEffect(() => {
    const node = host.current;
    if (!node) return;
    let alive = true;
    let fitted = -1;
    const fit = (width: number) => {
      if (!alive || width === fitted) return;
      fitted = width;
      const measure = width ? measurerFor(node) : null;
      if (!measure) {
        setVisible(value);
        return;
      }
      const fits = (candidate: string) => measure(candidate) <= width;
      if (fits(value)) {
        setVisible(value);
        return;
      }
      const suffixLength = Math.min(
        Math.max(0, Math.floor(keepEnd)),
        value.length,
      );
      let start = 0;
      let end = value.length;
      let result = "…";
      while (start <= end) {
        const count = Math.floor((start + end) / 2);
        const suffix = Math.min(suffixLength, count);
        const candidate = `${value.slice(0, count - suffix)}…${suffix ? value.slice(-suffix) : ""}`;
        if (fits(candidate)) {
          result = candidate;
          start = count + 1;
        } else end = count - 1;
      }
      setVisible(result);
    };
    const observer = new ResizeObserver(([entry]) =>
      fit(entry.contentRect.width),
    );
    observer.observe(node);
    const refit = () => {
      const width = fitted;
      fitted = -1;
      if (width >= 0) fit(width);
    };
    document.fonts?.addEventListener("loadingdone", refit);
    return () => {
      alive = false;
      observer.disconnect();
      document.fonts?.removeEventListener("loadingdone", refit);
    };
  }, [value, keepEnd]);
  return (
    <span
      ref={host}
      data-slot="middle-truncate"
      className={cn(styles.truncate, mono && styles.mono, className)}
      title={title === false ? undefined : (title ?? value)}
      onCopy={(event) => {
        onCopy?.(event);
        if (!event.defaultPrevented) {
          event.clipboardData.setData("text/plain", value);
          event.preventDefault();
        }
      }}
      {...props}
    >
      <span className="sr-only">{value}</span>
      <span aria-hidden="true">{visible}</span>
    </span>
  );
}
MiddleTruncate.displayName = "MiddleTruncate";

.truncate {
  display: inline-block;
  position: relative;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  vertical-align: bottom;
}
.mono {
  font-family: var(--cipher-font-mono, monospace);
}
.collapse {
  display: block;
}
.collapse[hidden] {
  display: none;
}
.collapseInner {
  min-height: 0;
}
.text {
  margin: 0;
  color: var(--cipher-ink, var(--foreground));
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
.small {
  margin: 0;
  color: var(--cipher-text2, var(--muted-foreground));
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.eyebrow {
  margin: 0;
  color: var(--cipher-muted, var(--muted-foreground));
  font-family: var(--cipher-type-eyebrow-font-family);
  font-size: var(--cipher-type-eyebrow-font-size);
  line-height: var(--cipher-type-eyebrow-line-height);
  font-weight: var(--cipher-type-eyebrow-font-weight);
  letter-spacing: var(--cipher-type-eyebrow-letter-spacing);
  text-transform: uppercase;
}
.muted {
  color: var(--cipher-muted, var(--muted-foreground));
}
.preWrap {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.endTruncate {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.meta.endTruncate {
  display: inline-block;
  vertical-align: bottom;
}
.measurePage {
  width: 100%;
  max-width: var(--cipher-size-measure-page);
  margin-inline: auto;
  padding: var(--cipher-space-content-section) var(--cipher-space-40);
}
.measureForm {
  width: 100%;
  max-width: var(--cipher-size-measure-form);
}
@media (max-width: 640px) {
  .measurePage {
    padding: var(--cipher-space-20) var(--cipher-space-16);
  }
}
.stack {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.inline {
  display: flex;
  min-width: 0;
}
.grid {
  display: grid;
  min-width: 0;
}
.inlineGrow {
  flex: 1 1 var(--cipher-size-text-min);
}
.inlineItem {
  display: flex;
  align-items: center;
}
.inlineItem.endTruncate {
  display: block;
}
.inlineFixed {
  flex-shrink: 0;
}
.stack > *,
.inline > *,
.grid > * {
  min-width: 0;
}
/* A fixed column count fits as many columns as the row's width allows, so the grid takes the row's width even where its parent would shrink it to its content. */
.gridColumns {
  align-self: stretch;
  justify-self: stretch;
}
.gridSplit {
  container-type: inline-size;
}
.gridSplit > * {
  grid-column: 1 / -1;
}
/* Container conditions cannot read custom properties, so this repeats size-sidecar-collapse (896px), the two-column breakpoint DetailLayout uses. */
@container (min-width: 896px) {
  .gridSplit > * {
    grid-column: auto;
  }
}
.container {
  width: 100%;
  min-width: 0;
  margin-inline: auto;
  max-width: var(--cipher-size-measure-page);
}
.measureProse {
  width: 100%;
  min-width: 0;
  max-width: var(--cipher-size-measure-prose);
}
.heading {
  margin: 0;
  color: var(--cipher-ink, var(--foreground));
  font-family: var(--cipher-heading-family);
  font-size: var(--cipher-heading-size);
  line-height: var(--cipher-heading-line);
  font-weight: var(--cipher-heading-weight);
  letter-spacing: var(--cipher-heading-tracking);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.heading[data-size="page"] {
  --cipher-heading-family: var(--cipher-type-title-lg-font-family);
  --cipher-heading-size: var(--cipher-type-title-lg-font-size);
  --cipher-heading-line: var(--cipher-type-title-lg-line-height);
  --cipher-heading-weight: var(--cipher-type-title-lg-font-weight);
  --cipher-heading-tracking: var(--cipher-type-title-lg-letter-spacing);
}
.heading[data-size="display"] {
  --cipher-heading-family: var(--cipher-type-display-font-family);
  --cipher-heading-size: var(--cipher-type-display-font-size);
  --cipher-heading-line: var(--cipher-type-display-line-height);
  --cipher-heading-weight: var(--cipher-type-display-font-weight);
  --cipher-heading-tracking: var(--cipher-type-display-letter-spacing);
}
.heading[data-size="section"] {
  --cipher-heading-family: var(--cipher-type-title-font-family);
  --cipher-heading-size: var(--cipher-type-title-font-size);
  --cipher-heading-line: var(--cipher-type-title-line-height);
  --cipher-heading-weight: var(--cipher-type-title-font-weight);
  --cipher-heading-tracking: var(--cipher-type-title-letter-spacing);
}
.heading[data-size="subsection"] {
  --cipher-heading-family: var(--cipher-type-title-sm-font-family);
  --cipher-heading-size: var(--cipher-type-title-sm-font-size);
  --cipher-heading-line: var(--cipher-type-title-sm-line-height);
  --cipher-heading-weight: var(--cipher-type-title-sm-font-weight);
  --cipher-heading-tracking: var(--cipher-type-title-sm-letter-spacing);
}
.meta {
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
  font-variant-numeric: tabular-nums;
  color: var(--cipher-muted, var(--muted-foreground));
}
.meta.mono {
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
}
.status {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-6);
  min-width: 0;
  vertical-align: top;
  color: var(--cipher-text2, var(--muted-foreground));
}
.status > svg {
  flex: none;
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
  stroke-width: var(--cipher-stroke-icon);
}
.status[data-size="sm"] {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.status[data-size="sm"] > svg {
  width: var(--cipher-size-icon-sm);
  height: var(--cipher-size-icon-sm);
}
.status[data-size="md"] {
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
.status[data-tone="ok"] {
  color: var(--cipher-ok);
}
.status[data-tone="warn"] {
  color: var(--cipher-warn);
}
.status[data-tone="bad"] {
  color: var(--cipher-bad);
}
.highlight {
  background-color: var(--cipher-accent);
  color: var(--cipher-on-accent);
}
